def main():
 static=read(OUT/'FIXTURE_STATIC_AUDIT.json');signed=read(OUT/'SIGNED_BILATERAL_CHECK.json');forward=read(OUT/'FIXTURE_FORWARD_AUDIT.json');normal=read(OUT/'NORMAL_LOAD_WRENCH_AUDIT.json');nf=read(OUT/'NORMAL_LOAD_FORWARD_AUDIT.json');full=read(OUT/'FULL_MODEL_SCALING_AND_DEFAULT_GATE.json');selection=read(OUT/'DERIVED_VARIANT.json')
 # Description-only correction: generalizedload is constant; anchorforce equivalent atclosedreference.
