 peak=max(r['maxgap_m'] for r in nf['cases']);decision=dict(scope='Numericalclosed-linkfixturefidelity only, not hardwarecalibration or robotstanding',source_mass_inertia_exact=static['proof']['body_mass_exact'] and static['proof']['body_inertia_exact'],singlehinge_signed_static_gate=signed['gate'],singlehinge_forward_gate=forward['selected_fixture_gate'] and forward['time_convergence_pass'],stronger_jointcouple_parent05mm_gate=nf['parent_05mm_gate'] and nf['half_quarter_converged'],original100um_target_met_all=False,normal_load_peak_gap_m=peak,default_off_matcheddata_exact=full['default_off']['qacc_exact'] and full['default_off']['constraint_force_exact'] and full['default_off']['all_selected_arrays_exact'],full_robot_trial_performed=False,old_BPA_geometry_unchanged=True,selection=selection);(OUT/'DECISION.json').write_text(json.dumps(decision,indent=2))
 import matplotlib;matplotlib.use('Agg')
