 axes[1].axhline(.1,color='.35',ls='-.',label='100 µm design target');axes[1].set_xlabel('Fixture time (s)');axes[1].set_ylabel('Gap under stronger left joint couple (mm)');axes[1].set_title('9 N m back / 13.05 N m shank step at 0.1 s');axes[1].legend(frameon=False,fontsize=8);axes[1].grid(alpha=.2);fig.suptitle('Source-inertia four-bar fixture: derived numerical rigid-link approximation\nSame source mass, inertia, lever arms, and joint damping; explicit external fixture hold',fontsize=11)
